INSERT INTO `biz_competition` (title, competition_type, level, organizer, co_organizer, description, requirements, rewards, registration_start, registration_end, competition_start, competition_end, location, contact, cover_image, official_url, status, view_count, created_by, id, created_at, updated_at, is_deleted) VALUES
  ('第十三届中国国际大学生创新大赛', 4, 3, '教育部、中央统战部、中央网信办等', '天津大学', '中国国际大学生创新大赛是教育部等部门联合主办的全国性大学生创新创业赛事，旨在深化高等教育综合改革，激发大学生的创造力，培养造就大众创业、万众创新的生力军。', '参赛对象为全日制在校学生（含本专科生、研究生）及毕业5年内的校友。项目需具有创新性、商业性和团队合作精神。', '设高教主赛道、青年红色筑梦之旅、产业命题赛道等，各赛道分设金奖、银奖、铜奖。', '2026-04-01 00:00:00', '2026-06-30 00:00:00', '2026-07-01 00:00:00', '2026-10-31 00:00:00', '天津市', '010-6609XXXX', '/images/competitions/poster_internet_plus.jpg', NULL, 1, 2, 1, 42, '2026-09-19 13:35:09', '2026-09-19 20:22:48', 0),
  ('第十八届挑战杯全国大学生课外学术科技作品竞赛', 4, 3, '共青团中央、中国科协、教育部、中国社会科学院、全国学联', '复旦大学', '挑战杯全国大学生课外学术科技作品竞赛是由共青团中央、中国科协、教育部、中国社会科学院、全国学联共同主办的全国性大学生课外学术实践竞赛。', '参赛作品分为自然科学类学术论文、哲学社会科学类社会调查报告和学术论文、科技发明制作三大类。', '设特等奖、一等奖、二等奖、三等奖，另设优秀组织奖、优秀指导教师奖等。', '2026-03-01 00:00:00', '2026-05-31 00:00:00', '2026-06-01 00:00:00', '2026-11-30 00:00:00', '上海市', '010-8521XXXX', '/images/competitions/poster_tiaozhanbei.jpg', NULL, 1, 0, 1, 43, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('2026年全国大学生数学建模竞赛', 3, 3, '中国工业与应用数学学会', '中国海洋大学', '全国大学生数学建模竞赛是教育部高教司和中国工业与应用数学学会共同主办的面向全国大学生的群众性科技活动。', '参赛队由三名在校本科生组成，专业不限。竞赛期间可查阅图书资料、使用计算机和互联网，但不得与队外任何人讨论。', '设一等奖、二等奖、三等奖，各等级比例分别不超过参赛队数的3%、7%、20%。', '2026-05-01 00:00:00', '2026-08-31 00:00:00', '2026-09-11 00:00:00', '2026-09-14 00:00:00', '线上', '010-6278XXXX', '/images/competitions/poster_math_modeling.jpg', NULL, 1, 0, 1, 44, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('2026年校级大学生创新创业训练计划项目申报', 1, 1, '校创新创业学院', '各二级学院', '校级大学生创新创业训练计划项目旨在促进高校转变教育思想观念，改革人才培养模式，强化创新创业能力训练，增强高校学生的创新能力和在创新基础上的创业能力。', '项目分为创新训练项目、创业训练项目和创业实践项目三类。申请人为全日制在校本科生，团队人数3-5人。', '创新训练项目资助1-2万元/项，创业训练项目资助2-3万元/项，创业实践项目资助5-10万元/项。', '2026-09-01 00:00:00', '2026-09-30 00:00:00', '2026-10-01 00:00:00', '2027-09-30 00:00:00', '本校', '0571-8888XXXX', '/images/competitions/poster_school_training.jpg', NULL, 1, 0, 1, 45, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('第十届浙江省大学生创新创业大赛', 4, 2, '浙江省教育厅、浙江省人力资源和社会保障厅', '浙江大学', '浙江省大学生创新创业大赛是浙江省内规模最大、影响力最广的大学生创新创业赛事，涵盖创新、创业、创意等多个赛道。', '浙江省内全日制普通高校在校学生（含研究生）及毕业5年内的校友均可参赛。', '设一等奖、二等奖、三等奖及优秀组织奖，获奖项目可获创业孵化支持。', '2026-04-15 00:00:00', '2026-06-15 00:00:00', '2026-07-01 00:00:00', '2026-09-30 00:00:00', '杭州市', '0571-8795XXXX', '/images/competitions/poster_zhejiang_cxcy.jpg', NULL, 1, 1, 1, 46, '2026-09-19 13:35:09', '2026-09-19 20:22:51', 0),
  ('中国创新创业大赛', 2, 3, '科技部、财政部、教育部、中央网信办、全国工商联', '科技部火炬高技术产业开发中心', '中国创新创业大赛是由科技部、财政部、教育部、中央网信办和全国工商联共同指导举办的全国性创新创业赛事，是国内规格最高、规模最大、影响力最广的创新创业品牌活动。', '参赛企业应为符合国家划型标准的中小企业，且注册时间不超过5年；团队组应拥有核心技术或创新产品，具有较好的商业前景。', '设一等奖、二等奖、三等奖及优胜奖，获奖项目可获得国家创新创业政策支持、创业投资对接、孵化场地等扶持。', '2026-05-01 00:00:00', '2026-07-31 00:00:00', '2026-08-01 00:00:00', '2026-11-30 00:00:00', '北京市', '010-8865XXXX', '/images/competitions/poster_cxcyds.jpg', NULL, 1, 0, 1, 47, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('"创青春"全国大学生创业大赛', 2, 3, '共青团中央、教育部、人力资源和社会保障部、中国科协、全国学联', '承办高校', '"创青春"全国大学生创业大赛是由共青团中央等单位共同主办的全国性大学生创业实践赛事，旨在引导和激励大学生弘扬创新精神，提升创业能力，培养创业人才。', '参赛对象为全国全日制普通高校在校学生（含本专科生、研究生）及毕业3年内的校友。参赛项目分为创业计划竞赛、创业实践挑战赛、公益创业赛等类别。', '设金奖、银奖、铜奖，另设最佳创意奖、最具人气奖、优秀组织奖等。获奖项目可获得创业孵化、投资对接等支持。', '2026-03-15 00:00:00', '2026-06-30 00:00:00', '2026-07-15 00:00:00', '2026-10-15 00:00:00', '线上+线下', '010-6707XXXX', '/images/competitions/poster_chuangqingchun.jpg', NULL, 1, 0, 1, 48, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('全国大学生电子商务"创新、创意及创业"挑战赛', 2, 3, '教育部高等学校电子商务类专业教学指导委员会', '承办高校', '全国大学生电子商务"创新、创意及创业"挑战赛（简称"三创赛"）是由教育部高等学校电子商务类专业教学指导委员会主办的全国性大学生学科竞赛，旨在激发大学生的创新意识、创意思维和创业能力。', '参赛队由3-5名在校本科生组成，配1-2名指导教师。参赛作品需围绕电子商务主题，具有创新性、创意性和可落地性。', '设特等奖、一等奖、二等奖、三等奖及最佳创新奖、最佳创意奖、最佳创业奖等单项奖。', '2026-04-01 00:00:00', '2026-06-30 00:00:00', '2026-07-01 00:00:00', '2026-10-31 00:00:00', '线上+线下', '010-6228XXXX', '/images/competitions/poster_ec_san_chuang.jpg', NULL, 1, 0, 1, 49, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('"中国创翼"创业创新大赛', 2, 3, '人力资源和社会保障部、国家发展改革委、科技部、共青团中央、中国残联', '承办地方人社部门', '"中国创翼"创业创新大赛是由人力资源和社会保障部等部门联合主办的全国性创业创新赛事，旨在营造创新创业氛围，激发创业创新热情，助力创业带动就业。', '参赛项目分为主体赛和专项赛。主体赛面向各类创业群体，专项赛面向青年、农民工、退役军人、残疾人等特定群体。项目需具有创新性和可持续性。', '设一等奖、二等奖、三等奖及优胜奖，获奖项目可获得创业担保贷款、创业补贴、孵化服务等政策扶持。', '2026-04-01 00:00:00', '2026-07-15 00:00:00', '2026-08-01 00:00:00', '2026-11-15 00:00:00', '全国各赛区', '010-8422XXXX', '/images/competitions/poster_zhongguochuangyi.jpg', NULL, 1, 0, 1, 50, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('iCAN国际创新创业大赛', 4, 4, 'iCAN国际创新创业大赛组委会', '国际MEMS协会、中国微米纳米技术学会', 'iCAN国际创新创业大赛是由国际MEMS协会和中国微米纳米技术学会联合发起的国际性创新创业赛事，聚焦微纳米技术、物联网、人工智能等前沿科技领域的创新应用。', '参赛对象为国内外高校在校学生及毕业3年内的青年创业者。参赛作品需基于微纳技术或相关前沿科技，具有创新性和应用价值。', '设特等奖、一等奖、二等奖、三等奖及最佳创新奖、最具商业价值奖等。获奖项目可获得国际交流、产业对接、投资孵化等支持。', '2026-03-01 00:00:00', '2026-06-30 00:00:00', '2026-07-01 00:00:00', '2026-10-31 00:00:00', '线上+国际赛区', '010-8264XXXX', '/images/competitions/poster_ican.jpg', NULL, 1, 0, 1, 51, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('全国大学生创新体验竞赛', 1, 3, '中国高等教育学会', '承办高校', '全国大学生创新体验竞赛是由中国高等教育学会主办的全国性大学生创新实践赛事，强调"创新体验"理念，鼓励大学生通过亲身体验发现问题、提出创意、完成创新作品。', '参赛对象为全国高校在校本科生。竞赛分为创新作品类、创新方法论类等赛道，参赛作品需体现创新思维和实践过程。', '设特等奖、一等奖、二等奖、三等奖及优秀组织奖、优秀指导教师奖。', '2026-03-15 00:00:00', '2026-05-31 00:00:00', '2026-06-15 00:00:00', '2026-09-30 00:00:00', '线上+线下', '025-8379XXXX', '/images/competitions/poster_innovation_experience.jpg', NULL, 1, 0, 1, 52, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  ('浙江省"挑战杯"大学生创业计划竞赛', 2, 2, '共青团浙江省委、浙江省教育厅、浙江省科协、浙江省学联', '承办高校', '浙江省"挑战杯"大学生创业计划竞赛是浙江省内级别最高的大学生创业赛事，作为全国"挑战杯"创业计划竞赛的省级选拔赛，选拔优秀项目代表浙江省参加全国总决赛。', '参赛对象为浙江省内全日制普通高校在校学生（含研究生）及毕业3年内的校友。参赛项目需具有完整的商业计划和可行性。', '设金奖、银奖、铜奖及优秀组织奖。获奖项目将推荐参加全国"挑战杯"创业计划竞赛，并可获得省级创业扶持。', '2026-03-01 00:00:00', '2026-05-15 00:00:00', '2026-06-01 00:00:00', '2026-09-30 00:00:00', '杭州市', '0571-8705XXXX', '/images/competitions/poster_zhejiang_tiaozhan.jpg', NULL, 1, 0, 1, 53, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0);
INSERT INTO `biz_announcement` (title, content, announcement_type, status, priority, publish_time, expire_time, view_count, created_by, id, created_at, updated_at, is_deleted) VALUES
  ('系统升级维护通知', '<p>尊敬的用户：</p><p>系统将于本周六凌晨进行升级维护，期间可能短暂无法访问，请提前做好准备。</p>', 1, 2, 1, '2026-09-18 19:16:26', '2020-01-01 00:00:00', 14, 1, 1, '2026-09-18 19:16:25', '2026-09-19 17:21:26', 0),
  ('测试永久有效公告', '<p>这是一条永久有效的公告内容</p>', 1, 1, 1, '2026-09-18 19:51:55', NULL, 1, 1, 2, '2026-09-18 19:51:54', '2026-09-18 19:53:51', 0),
  ('极客飒辅导费啦加快速度发哈拉卡', '阿德所发生的发放大手动阀s<br>发就发拒收到付晶科科技和', 1, 1, 1, '2026-09-18 19:54:43', NULL, 4, 1, 3, '2026-09-18 19:54:42', '2026-09-18 20:04:35', 0);
