INSERT INTO `proj_project` (id, project_no, project_name, project_type, project_level, college_id, leader_id, teacher_id, competition_id, start_date, end_date, budget_amount, used_amount, project_summary, innovation_points, expected_results, status, submit_time, approval_time, current_approver_id, reject_reason, created_at, updated_at, is_deleted) VALUES
  (70, NULL, '基于Vue+FastAPI的校园创新创业管理平台设计与实现', 1, 1, 4, 351, 645, 43, '2026-03-01 00:00:00', '2027-02-20 00:00:00', '20000.00', '0.00', '本项目旨在开发一套面向高校的创新创业项目管理平台，采用Vue3+FastAPI技术栈，实现项目申报、审核、经费管理、成果登记等全流程数字化管理，提升高校创新创业工作的管理效率与信息化水平。', '1.采用前后端分离架构，前端Vue3+Element Plus，后端FastAPI+SQLAlchemy，响应迅速、可扩展性强；2.集成AI智能助手，提供项目申报智能推荐、文本自动生成等辅助功能；3.支持多角色权限管理，涵盖学生、指导教师、评审专家、管理员四类角色的精细化权限控制。', '完成平台开发并部署上线，实现项目申报、审核、经费、成果等核心模块；发表学术论文1篇；申请软件著作权1项。', 0, NULL, NULL, NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (71, NULL, '基于深度学习的校园智能安防监控系统', 1, 2, 6, 521, 662, 53, '2026-04-25 00:00:00', '2027-04-03 00:00:00', '15000.00', '0.00', '针对传统校园安防监控依赖人工值守、响应滞后的问题，本项目设计并实现一套基于深度学习的智能安防监控系统。系统集成目标检测、行为识别、异常告警等功能，可对校园重点区域进行7×24小时智能监测，及时发现并预警安全隐患。', '1.采用YOLOv8目标检测算法，结合校园场景数据集进行迁移学习，识别准确率达95%以上；2.设计多模态融合的异常行为识别模型，综合视频帧与音频特征进行联合判断；3.实现边缘端轻量化部署，支持在普通监控设备上实时运行。', '完成系统原型开发并在校园试点部署；申请发明专利1项、实用新型专利1项；发表EI会议论文1篇。', 0, NULL, NULL, NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (72, 'IE2026000003', '智慧农业物联网监测与精准灌溉系统', 1, 2, 2, 194, 621, 52, '2026-03-01 00:00:00', '2027-02-26 00:00:00', '50000.00', '0.00', '面向现代农业精细化管理需求，开发一套基于物联网的智慧农业监测与精准灌溉系统。系统通过部署在田间的各类传感器实时采集土壤温湿度、光照强度、CO2浓度等环境数据，结合气象预报与作物生长模型，实现灌溉量的智能决策与自动控制。', '1.设计低功耗无线传感器网络节点，采用休眠-唤醒机制延长电池寿命至2年以上；2.构建基于LSTM的作物需水量预测模型，灌溉决策准确率较传统方法提升30%；3.支持移动端远程监控与手动干预，农户可随时随地掌握农田状况。', '完成硬件原型与软件平台开发；在试验田部署验证节水率达25%以上；申请软件著作权2项、实用新型专利1项。', 12, '2026-09-19 16:17:45', NULL, 621, NULL, '2026-09-19 13:35:09', '2026-09-19 16:17:45', 0),
  (73, 'IE2026000004', '面向大学生的闲置物品共享交易平台', 3, 1, 6, 569, 666, 51, '2026-03-28 00:00:00', '2027-01-21 00:00:00', '30000.00', '0.00', '针对大学校园闲置物品流通不畅、资源浪费严重的现状，打造一款专注于校园场景的闲置物品共享交易平台。平台提供二手书、电子产品、生活用品等品类的发布、搜索、交易功能，并引入信用评价与校园实名认证机制，保障交易安全。', '1.创新采用基于地理位置与社交关系的推荐算法，优先展示同校及周边用户的闲置物品；2.设计物品溯源与真伪鉴别机制，针对电子产品提供序列号验证服务；3.推出以物易物功能，支持物品直接交换，降低交易门槛。', '完成平台开发并上线运营，注册用户突破5000人，月交易额达10万元；形成完整的商业计划书；冲击互联网+大学生创新创业大赛省级奖项。', 3, '2026-03-22 11:00:00', NULL, 7, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (74, 'IE2026000005', '基于区块链的高校学历证书存证系统', 1, 3, 5, 478, 653, 49, '2026-04-16 00:00:00', '2027-01-05 00:00:00', '20000.00', '0.00', '针对传统学历证书易伪造、验证流程繁琐的痛点，设计并实现一套基于区块链技术的高校学历证书存证与验证系统。系统将证书关键信息上链存证，用人单位可通过扫码或输入证书编号快速验证真伪，有效杜绝学历造假。', '1.采用联盟链架构，由高校、教育主管部门、用人单位共同组成验证节点，兼顾去中心化与权威性；2.设计基于零知识证明的隐私保护方案，验证方无需获取证书全文即可确认其真实性；3.支持批量上链与批量验证，满足高校毕业季大规模发证需求。', '完成系统设计与核心模块开发；在试点高校完成小规模部署验证；发表核心期刊论文1篇；申请发明专利1项。', 5, '2026-04-09 14:00:00', NULL, 1, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (75, 'IE2026000006', '智能语音交互的图书馆座位预约小程序', 1, 1, 2, 114, 619, 53, '2026-04-28 00:00:00', '2027-02-22 00:00:00', '15000.00', '172.05', '为解决高校图书馆座位管理混乱、占座现象严重的问题，开发一款支持智能语音交互的图书馆座位预约微信小程序。学生可通过语音或文字查询空座、预约座位、临时离开、退座等，图书馆管理员可实时监控座位使用情况并进行管理。', '1.集成智能语音识别与语义理解，支持自然语言座位查询，如三楼靠窗还有空位吗；2.设计基于用户行为画像的座位推荐算法，根据历史使用习惯推荐合适座位；3.引入信用积分机制，对违约占座行为进行约束。', '完成小程序开发并在校内图书馆试点运行，日活跃用户达800人以上；申请软件著作权1项；发表论文1篇。', 12, '2026-04-14 15:00:00', '2026-06-11 09:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (76, 'IE2026000007', '基于机器视觉的工件表面缺陷检测系统', 1, 2, 4, 326, 646, 46, '2026-03-19 00:00:00', '2026-12-08 00:00:00', '50000.00', '10922.10', '面向制造业质检环节对自动化、高精度的需求，开发一套基于机器视觉的工件表面缺陷检测系统。系统通过工业相机采集工件表面图像，利用深度学习算法自动识别划痕、凹陷、污渍等缺陷类型并定位，实现质检环节的智能化升级。', '1.设计多尺度特征融合的缺陷检测网络，对小尺寸缺陷的检出率达98%；2.提出基于迁移学习的少样本训练策略，仅需少量标注样本即可达到较高检测精度；3.支持在线实时检测，处理速度达30帧/秒，满足产线节拍要求。', '完成算法模型开发与检测系统搭建；在合作企业产线完成测试验证；申请发明专利1项、软件著作权1项。', 6, '2026-03-09 09:00:00', '2026-04-14 14:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (77, 'IE2026000008', '校园二手教材循环利用服务平台', 3, 1, 2, 163, 621, 53, '2026-03-05 00:00:00', '2026-10-24 00:00:00', '15000.00', '6133.72', '针对高校教材使用周期短、浪费严重的问题，打造校园二手教材循环利用服务平台。平台连接毕业生与在校生，提供教材回收、消毒、租赁、转售等一体化服务，降低学生购书成本，推动绿色校园建设。', '1.建立教材成色智能评估模型，通过拍照识别教材破损程度并给出回收估价；2.设计教材流通溯源系统，记录每本教材的流转历史，保障卫生安全；3.推出教材订阅制服务，学生按学期订阅所需教材，费用仅为新书的30%。', '完成平台开发与运营体系搭建；覆盖3所高校，回收教材2万册以上；形成可持续的商业模式。', 6, '2026-02-19 18:00:00', '2026-04-16 17:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (78, 'IE2026000009', '基于增强现实的机械装配实训系统', 1, 3, 3, 208, 630, NULL, '2026-03-26 00:00:00', '2026-12-06 00:00:00', '30000.00', '11713.71', '针对机械类专业实训设备昂贵、操作风险高的问题，开发一套基于增强现实（AR）技术的机械装配实训系统。学生佩戴AR设备即可在虚拟环境中完成齿轮箱、发动机等复杂机构的拆装训练，系统实时提供操作引导与错误纠正。', '1.采用空间锚定技术实现虚拟模型与真实工作台的精准对齐，误差小于2mm；2.设计基于手势识别的自然交互方式，支持抓取、旋转、装配等操作；3.构建智能化评分系统，根据操作步骤的完整性与规范性自动打分。', '完成核心功能开发与3D模型制作；在机械工程学院实训课程中试点应用；申请发明专利1项、软件著作权2项。', 7, '2026-03-16 09:00:00', '2026-04-20 16:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (79, 'IE2026000010', '面向独居老人的智能跌倒检测与报警手环', 3, 2, 2, 117, 623, 49, '2026-03-15 00:00:00', '2026-09-27 00:00:00', '30000.00', '15157.40', '针对独居老人跌倒后无法及时求助的社会痛点，研发一款集跌倒检测、健康监测、紧急报警于一体的智能手环。手环内置六轴加速度传感器与心率监测模块，可实时识别跌倒事件并自动通知紧急联系人与社区服务中心。', '1.设计基于阈值判定与机器学习相结合的跌倒检测算法，灵敏度达99%，误报率低于1%；2.采用低功耗设计，单次充电续航达7天；3.集成一键SOS与语音通话功能，操作简单，适合老年人使用。', '完成手环硬件设计与配套APP开发；开展100人规模的用户测试；申请实用新型专利2项、外观专利1项。', 8, '2026-03-08 18:00:00', '2026-05-04 10:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (80, 'IE2026000011', '基于知识图谱的高校就业推荐系统', 1, 1, 2, 118, 624, 47, '2026-03-01 00:00:00', '2026-11-27 00:00:00', '20000.00', '9916.73', '针对大学生就业信息不对称、人岗匹配度低的问题，构建基于知识图谱的高校就业推荐系统。系统整合岗位信息、毕业生画像、企业需求等多源数据，通过知识推理实现精准的人岗匹配与就业路径推荐。', '1.构建涵盖岗位技能、专业课程、能力素质的就业知识图谱，实体规模超10万；2.设计基于图神经网络的推荐算法，推荐准确率较协同过滤方法提升20%；3.支持就业竞争力评估，为学生提供能力提升建议。', '完成系统开发与知识图谱构建；在就业指导中心试点应用；发表论文1篇、申请软件著作权1项。', 9, '2026-02-14 11:00:00', '2026-04-08 15:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (81, 'IE2026000012', '校园无人配送小车路径规划与调度系统', 1, 2, 4, 373, 644, 43, '2026-04-11 00:00:00', '2027-02-10 00:00:00', '10000.00', '1363.01', '面向校园末端配送需求，开发一套无人配送小车的路径规划与多车调度系统。系统基于校园高精度地图，综合考虑配送时效、车辆载荷、障碍物等因素，为多辆配送小车生成最优配送路径并实现动态调度。', '1.设计改进A*算法结合时间窗约束的路径规划方法，有效避免多车碰撞；2.提出基于遗传算法的订单分配与车辆调度优化策略，配送效率提升25%；3.支持实时路况更新与动态重规划，应对突发情况。', '完成算法开发与仿真验证；与校园快递合作开展小规模试运行；申请发明专利1项。', 9, '2026-03-31 17:00:00', '2026-05-04 10:00:00', NULL, NULL, '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (82, 'IE2026000013', '基于物联网的智能教室环境监测与调控系统', 1, 1, 4, 367, 644, NULL, '2026-03-16 00:00:00', '2026-12-24 00:00:00', '20000.00', '5315.91', '针对传统教室环境监测手段落后、能耗浪费严重的问题，开发一套基于物联网技术的智能教室环境监测与调控系统。系统实时采集教室温度、湿度、CO2浓度、光照强度等参数，通过智能算法自动调节空调、照明、通风设备，为师生创造舒适的学习环境，同时降低能耗。', '1.设计多传感器数据融合算法，提高环境参数监测精度；2.提出基于人体感应与课程表的智能调控策略，避免无人时段能源浪费；3.支持远程监控与手动控制，管理员可通过手机APP实时管理教室设备。', '完成系统原型开发与试点部署；实现节能率20%以上；申请软件著作权1项、实用新型专利1项。', 10, '2026-03-10 13:00:00', '2026-05-04 17:00:00', NULL, '项目预算明细不清晰，建议补充具体费用说明后重新提交。', '2026-09-19 13:35:09', '2026-09-19 13:35:09', 0),
  (83, 'IE2026000014', '基于Vue+Django的校园互助系统', 3, 2, 1, 8, 608, 43, '2026-09-19 00:00:00', '2026-10-03 00:00:00', '12000.00', '0.00', '项目基于 Vue+Django 开发校园互助系统，面向高校学生，提供闲置交换、学业帮扶、物品借用等校园互助服务。平台依托校园实名认证保障信息安全，解决校内供需信息分散、线下互助缺乏信任保障的痛点。项目以校内试点运营起步，采用轻平台运营模式，逐步扩大高校覆盖范围，构建可信高效的校园互助生态。', '<p>1. **产品创新**：面向高校校园场景一体化设计互助平台，整合闲置流转、学业帮扶、物品租借、校园代办四大模块，依托校园实名认证体系建立校内信用机制，区别于通用二手平台，针对性解决校内供需信息零散、交易信任不足的痛点，更贴合大学生使用习惯。</p><p>2. **技术壁垒**：采用 Vue 前端 + Django 后端轻量化开发架构，搭建校内消息推送、订单管理、评价信用子系统，实现前后端分离的 Web 应用。适配校园内网访问，数据隔离保障学生隐私，可快速迭代功能，同类校园平台较少实现多互助业务一体化整合。</p><p>3. **商业模式创新**：采用**校内免费基础服务 + 增值服务**双轮驱动模式，基础互助发布功能免费吸引用户，通过置顶曝光、优先匹配等增值服务获取收益；以本校为试点，验证模式后横向拓展至周边高校，校园细分市场稳定，具备可持续运营潜力。</p>', '<p>1. 商业计划：完成完整创业计划书 1 份，包含市场分析、产品方案、运营策略、财务预测、风险防控等模块。</p><p>2. 原型产品：完成 MVP 最小可行校园互助系统开发，实现发布、接单、评价、消息通知核心功能，在本校开展内测，获取首批学生种子用户验证。</p><p>3. 竞赛目标：参加第十八届挑战杯，冲击省赛奖项，力争晋级更高赛事。</p><p>4. 创业落地：完善产品迭代，在校内常态化运营，持续积累用户，探索校园服务商业化路径。</p>', 7, '2026-09-19 15:08:47', '2026-09-19 20:22:30', NULL, NULL, '2026-09-19 15:04:45', '2026-09-19 20:24:57', 0);
